};

const files = ["a", "b", "c", "d", "e", "f", "g", "h"];
const ranks = ["8", "7", "6", "5", "4", "3", "2", "1"];

let state = null;
let selectedSquare = null;
let busy = false;
let busyStatus = "Thinking…";
let interactionStatus = null;
let pollInFlight = false;

