  }
}

async function startNewGame() {
  busy = true;
  busyStatus = "Starting…";
  selectedSquare = null;
  interactionStatus = null;
  errorElement.textContent = "";
  render();
  try {
    state = await request("/api/reset", { method: "POST" });
  } catch (error) {
    errorElement.textContent = error.message;
  } finally {
    busy = false;
    render();
  }
